#include <iostream>
#include <string>
#include <cctype>

class BookingMessageBuilder {
public:
    static std::string build(const std::string& type, const std::string& user_id, const std::string& booking_id) {
        std::string message = "[" + type + "] Dear " + user_id + ", your " + type + " " + booking_id + " is confirmed.";
